            _fee_msg = message.lower()
            _fee_type = None
            if re.search(r'\bnisd\b|\b0153\b', _fee_msg):
                _fee_type = "NISD"
            elif re.search(r'\bisd\b|\b0154\b', _fee_msg):
                _fee_type = "ISD"
